import { For } from '@pyreon/core'
import { signal } from '@pyreon/reactivity'
import { debounce, search, sortBy } from '@pyreon/rx'

const products = signal<Product[]>(initial)
const query = signal('')

function ProductList() {
  // built in the component: the debounce's effect and timer go away on unmount
  const visible = sortBy(search(products, debounce(query, 300), ['name']), 'price')
  // no subscribe, no unsubscribe
  return (
    <ul>
      <For each={visible} by={(p) => p.id}>{(p) => <li>{p.name}</li>}</For>
    </ul>
  )
}

