import { countBy, groupBy, sum } from '@pyreon/rx'

const revenue = sum(orders, 'total')
const perStatus = countBy(orders, 'status')
const byRegion = groupBy(orders, 'region')

const Tile = () => (
  <section>
    <h3>{() => revenue().toFixed(2)}</h3>
    <p>{() => perStatus().paid ?? 0} paid</p>
    <p>{() => Object.keys(byRegion()).length} regions</p>
  </section>
)

